<?php
require_once '../../config/db.php';require_once '../../vendor/autoload.php';require_once '../../config/invoice_renderer.php';if(session_status()===PHP_SESSION_NONE)session_start();if(!isset($_SESSION['user_id']))redirect('../../index.php');$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT i.*,c.company_name,c.contact_person,c.email,c.billing_address,cur.symbol FROM invoices i JOIN contacts c ON c.id=i.contact_id JOIN currencies cur ON cur.code=i.currency_code WHERE i.id=?');$s->execute([$id]);$invoice=$s->fetch();if(!$invoice){http_response_code(404);exit('Invoice not found.');}$s=$pdo->prepare('SELECT * FROM invoice_lines WHERE invoice_id=? ORDER BY id');$s->execute([$id]);$lines=$s->fetchAll();$s=$pdo->prepare('SELECT * FROM invoice_templates WHERE id=?');$s->execute([$invoice['invoice_template_id']]);$template=$s->fetch();if(!$template)$template=$pdo->query('SELECT * FROM invoice_templates ORDER BY is_default DESC,id LIMIT 1')->fetch();$document=render_invoice_document($pdo,$invoice,$lines,$template,true);$html='<!doctype html><html><head><meta charset="utf-8"><style>@page{margin:28px}body{margin:0;font-family:Helvetica,Arial,sans-serif}*{box-sizing:border-box}</style></head><body>'.$document.'</body></html>';$options=new Dompdf\Options();$options->set('isRemoteEnabled',false);$options->setChroot(dirname(__DIR__,2));$dompdf=new Dompdf\Dompdf($options);$dompdf->loadHtml($html,'UTF-8');$dompdf->setPaper('A4','portrait');$dompdf->render();$canvas=$dompdf->getCanvas();$canvas->page_text(500,810,'Page {PAGE_NUM} of {PAGE_COUNT}',null,8,[0.4,0.45,0.5]);$filename=preg_replace('/[^A-Za-z0-9_-]/','_',$invoice['invoice_number']).'.pdf';$dompdf->stream($filename,['Attachment'=>true]);
